arguments.content:
"""Replay each held-out (test-split) episode's verifier rule against a no-op episode.

Mirrors the training bridge exactly:
  - build final.db from gen_db.jsonl DDL + gen_sample.jsonl inserts (like
    awm.core.reset / awm.core.server._prepare_database), copy to initial.db
  - select rule: FIRST entry in gen_verifier.pure_code.jsonl matching
    (normalize_scenario_name(scenario), task_idx)  [find_scenario_entry]
  - run rule like awm.core.verify.run_verifier/execute_code_verifier:
    namespace {sqlite3, json, os, re, __builtins__}, first `def verify_` func,
    called with (initial_db_path, final_db_path, final_answer)
A no-op episode (initial == final) must classify as "others" for every task.
Read-only, no training, no network.
"""
import json
import os
import re
import sqlite3
import sys
import tempfile
from collections import Counter

BASE = "/workspace/data/AgentWorldModel-1K"
VERIFIER = f"{BASE}/gen_verifier.pure_code.jsonl"
TMP = tempfile.mkdtemp(prefix="noop_replay_")
os.makedirs(TMP, exist_ok=True)

def norm(s):
    s = s.lower()
    s = re.sub(r'[^a-z0-9_]', '_', s)
    s = re.sub(r'_+', '_', s).strip('_').strip()
    return s

# ---- load parquet without pandas ----
def read_parquet_keys(path):
    import pyarrow.parquet as pq
    t = pq.read_table(path)
    col = t.column("env_kwargs").to_pylist()
    keys = []
    for ew in col:
        if isinstance(ew, dict) and "py/object" in str(ew)[:200]:
            raise RuntimeError("pickle-encoded env_kwargs?")
        if isinstance(ew, str):
            ew = json.loads(ew)
        keys.append((norm(ew["scenario"]), ew["task_idx"], ew["task"]))
    return keys

try:
    test_keys = read_parquet_keys(f"{BASE}/verl/test.parquet")
except ImportError:
    import pandas as pd
    df = pd.read_parquet(f"{BASE}/verl/test.parquet")
    test_keys = []
    for ew in df["env_kwargs"]:
        if isinstance(ew, str):
            ew = json.loads(ew)
        test_keys.append((norm(ew["scenario"]), ew["task_idx"], ew["task"]))
print(f"test episodes: {len(test_keys)}")

# ---- gen_db / gen_sample indexed by normalized scenario ----
db_by_norm = {}
with open(f"{BASE}/gen_db.jsonl") as f:
    for line in f:
        e = json.loads(line)
        db_by_norm.setdefault(norm(e["scenario"]), e)
sample_by_norm = {}
with open(f"{BASE}/gen_sample.jsonl") as f:
    for line in f:
        e = json.loads(line)
        sample_by_norm.setdefault(norm(e["scenario"]), e)

def build_db(scenario_norm, db_path):
    """Create the DB like awm.core.db.create_sqlite_database + execute_sample_data."""
    schema = db_by_norm[scenario_norm]["db_schema"]
    stmt_failed = []
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    for table in schema.get("tables", []):
        ddl = table.get("ddl", "").strip()
        if ddl:
            try:
                cur.execute(ddl)
            except Exception as e:
                stmt_failed.append(("DDL", table.get("name"), repr(e)))
        for idx in table.get("indexes", []) or []:
            idx = idx.strip() if isinstance(idx, str) else str(idx)
            if idx:
                try:
                    cur.execute(idx)
                except Exception as e:
                    stmt_failed.append(("INDEX", idx, repr(e)))
    conn.commit()
    sample = sample_by_norm[scenario_norm]["sample_data"]
    for tbl in sample.get("tables", []):
        for ins in tbl.get("insert_statements", []):
            try:
                cur.execute(ins)
            except Exception as e:
                stmt_failed.append(("INSERT", ins[:120], repr(e)))
    conn.commit()
    conn.close()
    return stmt_failed

# ---- verifier file, first-match selection like find_scenario_entry ----
verifiers = []
with open(VERIFIER) as f:
    for i, line in enumerate(f):
        verifiers.append((i, json.loads(line)))

def find_rule(scenario_norm, task_idx):
    for i, e in verifiers:
        if norm(e.get("scenario", "")) != scenario_norm:
            continue
        if e.get("task_idx") != task_idx:
            continue
        return i, e
    return None, None

def run_rule(code, initial_db, final_db, final_answer=""):
    """Mirrors awm.core.verify.run_verifier (code mode)."""
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return "judge_error", {"error": "No valid verifier code found"}
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip()
            break
    namespace = {"sqlite3": sqlite3, "json": json, "os": os, "re": re,
                 "__builtins__": __builtins__}
    try:
        exec(code, namespace)
    except SyntaxError as e:
        return "judge_error", {"error": f"SyntaxError: {e}"}
    except Exception as e:
        return "judge_error", {"error": f"exec error: {e!r}"}
    fn = namespace.get(func_name)
    if not fn:
        return "judge_error", {"error": f"Function '{func_name}' not found"}
    try:
        result = fn(initial_db, final_db, final_answer)
    except Exception as e:
        return "judge_error", {"error": f"call error: {e!r}"}
    if not isinstance(result, dict) or "result" not in result:
        return "bad_return", {"raw": str(result)[:200]}
    rv = result.get("result", "others")
    if rv not in ("complete", "others"):
        rv = "others"
    return rv, result

results = Counter()
anomalies = []
for scen, tidx, task in test_keys:
    env_dir = os.path.join(TMP, f"{scen}__{tidx}")
    os.makedirs(env_dir, exist_ok=True)
    final_db = os.path.join(env_dir, "final.db")
    initial_db = os.path.join(env_dir, "initial.db")
    fails = build_db(scen, final_db)
    import shutil
    shutil.copy2(final_db, initial_db)
    line_no, rule = find_rule(scen, tidx)
    if rule is None:
        anomalies.append(("NO_RULE", scen, tidx, task[:80]))
        results["no_rule"] += 1
        continue
    code = rule.get("verification", {}).get("code", "")
    verdict, detail = run_rule(code, initial_db, final_db)
    results[verdict] += 1
    if verdict != "others":
        anomalies.append((verdict, f"{scen}/{tidx}", f"line{line_no}",
                           json.dumps(detail, default=str)[:300],
                           task[:100]))

print("\nno-op episode verdicts over 128 held-out episodes:", dict(results))
print("\nanomalies:")
for a in anomalies:
    print(" -", a)
print("\nsample-insert failures per scenario (nonempty only):")
for scen, tidx, task in test_keys:
    env_dir = os.path.join(TMP, f"{scen}__{tidx}")
    # already counted; recheck quickly
fail_set = {}
for scen, tidx, task in test_keys:
    env_dir = os.path.join(TMP, f"{scen}__{tidx}", "final.db")
    # skip
print("TMP:", TMP)

