# TASK: Search for the stock symbol 'AAPL', add it to a new watchlist named 'Tech Giants', and set a price alert to notify me when it falls below $180.
# ====================================================================================================
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check 1: Verify watchlist 'Tech Giants' exists for user_id=1
    watchlist_query = "SELECT id FROM watchlists WHERE user_id = ? AND name = ?"
    final_watchlists = safe_query(final_db_path, watchlist_query, (1, 'Tech Giants'))

    if not final_watchlists:
        return {"result": "others"}

    watchlist_id = final_watchlists[0][0]

    # Check 2: Verify AAPL (asset_id=1) is in the 'Tech Giants' watchlist
    # First get asset_id for AAPL
    asset_query = "SELECT id FROM assets WHERE symbol = ? AND asset_type = ?"
    aapl_assets = safe_query(final_db_path, asset_query, ('AAPL', 'stock'))

    if not aapl_assets:
        return {"result": "others"}

    aapl_asset_id = aapl_assets[0][0]

    # Check if AAPL is in the watchlist
    watchlist_item_query = "SELECT id FROM watchlist_items WHERE watchlist_id = ? AND asset_id = ?"
    watchlist_items = safe_query(final_db_path, watchlist_item_query, (watchlist_id, aapl_asset_id))

    if not watchlist_items:
        return {"result": "others"}

    # Check 3: Verify price alert exists for AAPL below $180
    alert_query = """SELECT id FROM price_alerts 
                     WHERE user_id = ? AND asset_id = ? 
                     AND direction = ? AND threshold_price = ? 
                     AND is_active = ?"""
    alerts = safe_query(final_db_path, alert_query, (1, aapl_asset_id, 'below', 180.0, 1))

    if not alerts:
        return {"result": "others"}

    # All three conditions met
    return {"result": "complete"}

# TASK: As a volunteer, update my profile to add the skills 'Spanish language', 'First Aid', and 'Event Coordination', set my interests to 'Youth programs' and 'Health outreach', and define my recurring availability as Mondays and Wednesdays from 17:00–20:00.
# ====================================================================================================
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Target user_id (volunteer_alice)
    user_id = 1

    # Expected skills: Spanish language (1), First Aid (2), Event Coordination (3)
    expected_skill_ids = {1, 2, 3}

    # Expected interests: Youth programs (1), Health outreach (2)
    expected_interest_ids = {1, 2}

    # Expected availability: Monday (1) and Wednesday (3), both 17:00-20:00
    expected_availability = [
        (1, '17:00', '20:00'),  # Monday
        (3, '17:00', '20:00')   # Wednesday
    ]

    # Check skills in final database
    final_skills_query = "SELECT skill_id FROM volunteer_skills WHERE user_id = ?"
    final_skills = safe_query(final_db_path, final_skills_query, (user_id,))
    final_skill_ids = {row[0] for row in final_skills}

    # Verify all expected skills are present
    if not expected_skill_ids.issubset(final_skill_ids):
        return {"result": "others"}

    # Check interests in final database
    final_interests_query = "SELECT interest_id FROM volunteer_interests WHERE user_id = ?"
    final_interests = safe_query(final_db_path, final_interests_query, (user_id,))
    final_interest_ids = {row[0] for row in final_interests}

    # Verify exactly the expected interests are present
    if final_interest_ids != expected_interest_ids:
        return {"result": "others"}

    # Check recurring availability in final database
