"""No-op replay across ALL train-split keys (per-scenario DB, all 10 task rules)."""
import json, os, re, sqlite3, shutil, sys, tempfile
from collections import Counter

BASE = "/workspace/data/AgentWorldModel-1K"
TMP = tempfile.mkdtemp(prefix="noop_train_")

def norm(s):
    s = s.lower(); s = re.sub(r'[^a-z0-9_]', '_', s); s = re.sub(r'_+', '_', s).strip('_').strip(); return s

import pandas as pd
df = pd.read_parquet(f"{BASE}/verl/train.parquet")
keys = []
for ew in df["env_kwargs"]:
    if isinstance(ew, str): ew = json.loads(ew)
    keys.append((norm(ew["scenario"]), ew["task_idx"], ew["task"]))
print("train episodes:", len(keys), file=sys.stderr)

db_by_norm, sample_by_norm = {}, {}
with open(f"{BASE}/gen_db.jsonl") as f:
    for line in f:
        e = json.loads(line); db_by_norm.setdefault(norm(e["scenario"]), e)
with open(f"{BASE}/gen_sample.jsonl") as f:
    for line in f:
        e = json.loads(line); sample_by_norm.setdefault(norm(e["scenario"]), e)

def build_db(scen_norm, db_path):
    conn = sqlite3.connect(db_path); cur = conn.cursor()
    for table in db_by_norm[scen_norm]["db_schema"].get("tables", []):
        if table.get("ddl","").strip(): cur.execute(table["ddl"].strip())
        for idx in table.get("indexes", []) or []:
            if isinstance(idx, str) and idx.strip(): cur.execute(idx)
    conn.commit()
    for tbl in sample_by_norm[scen_norm]["sample_data"].get("tables", []):
        for ins in tbl.get("insert_statements", []):
            try: cur.execute(ins)
            except Exception: pass
    conn.commit(); conn.close()

verifiers = []
with open(f"{BASE}/gen_verifier.pure_code.jsonl") as f:
    for i, line in enumerate(f):
        verifiers.append((i, json.loads(line)))

def find_rule(scen_norm, tidx):
    for i, e in verifiers:
        if norm(e.get("scenario","")) != scen_norm: continue
        if e.get("task_idx") != tidx: continue
        return i, e
    return None, None

def run_rule(code, initial_db, final_db, final_answer=""):
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return "judge_error", {}
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip(); break
    ns = {"sqlite3": sqlite3, "json": json, "os": os, "re": re, "__builtins__": __builtins__}
    try:
        exec(code, ns)
    except Exception as e:
        return "judge_error", {"err": f"exec: {e!r}"[:150]}
    fn = ns.get(func_name)
    if not fn: return "judge_error", {"err": f"no func {func_name}"}
    try:
        result = fn(initial_db, final_db, final_answer)
    except Exception as e:
        return "judge_error", {"err": f"call: {e!r}"[:150]}
    if not isinstance(result, dict) or "result" not in result:
        return "bad_return", {"err": str(result)[:100]}
    rv = result.get("result", "others")
    if rv not in ("complete", "others"): rv = "others"
    return rv, {}

from collections import defaultdict
keys_by_scen = defaultdict(list)
for k in keys: keys_by_scen[k[0]].append(k)

results = Counter()
anomalies = []
env_dirs = {}
for n, (scen, ks) in enumerate(keys_by_scen.items()):
    env_dir = os.path.join(TMP, scen); os.makedirs(env_dir, exist_ok=True)
    final_db = os.path.join(env_dir, "final.db"); initial_db = os.path.join(env_dir, "initial.db")
    build_db(scen, final_db); shutil.copy2(final_db, initial_db)
    for scen_, tidx, task in ks:
        line_no, rule = find_rule(scen, tidx)
        if rule is None:
            anomalies.append(("NO_RULE", scen, tidx)); results["no_rule"] += 1; continue
        code = rule.get("verification", {}).get("code", "")
        v, det = run_rule(code, initial_db, final_db)
        results[v] += 1
        if v == "complete":
            anomalies.append((scen, tidx, f"line{line_no}"))
    if n % 100 == 0:
        print(f"  ...{n} scenarios done", file=sys.stderr)

print("TRAIN no-op verdicts:", dict(results))
print("always-complete-on-noop train episodes:", len([a for a in anomalies if a[0] != 'NO_RULE']))
out = "/tmp/awmdiag/train_noop_complete.json"
with open(out, "w") as f:
    json.dump(anomalies, f, indent=1)
print("saved:", out, "TMP:", TMP)

