(call argument), and whether the code text mentions 'initial' at all.
Read-only; runs rules in the same namespace the bridge verifier uses."""
import ast, json, os, re, sqlite3, sys, tempfile
from collections import Counter, defaultdict

BASE = "/workspace/data/AgentWorldModel-1K"
TMP = tempfile.mkdtemp(prefix="full_sweep_")

def norm(s):
    s = s.lower(); s = re.sub(r'[^a-z0-9_]', '_', s); s = re.sub(r'_+', '_', s).strip('_').strip(); return s

db_by_norm, sample_by_norm = {}, {}
with open(f"{BASE}/gen_db.jsonl") as f:
    for line in f:
        e = json.loads(line); db_by_norm.setdefault(norm(e["scenario"]), e)
with open(f"{BASE}/gen_sample.jsonl") as f:
    for line in f:
        e = json.loads(line); sample_by_norm.setdefault(norm(e["scenario"]), e)

def build_db(sn, db_path):
    conn = sqlite3.connect(db_path); cur = conn.cursor()
    for table in db_by_norm[sn]["db_schema"].get("tables", []):
        if table.get("ddl","").strip(): cur.execute(table["ddl"].strip())
        for idx in table.get("indexes", []) or []:
            if isinstance(idx, str) and idx.strip(): cur.execute(idx)
    conn.commit()
    for tbl in sample_by_norm[sn]["sample_data"].get("tables", []):
        for ins in tbl.get("insert_statements", []):
            try: cur.execute(ins)
            except Exception: pass
    conn.commit(); conn.close()

def uses_initial(code):
    """AST: does any Call node pass initial_db_path as an argument (beyond the def signature)?"""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return None
    found = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            for a in node.args:
                if isinstance(a, ast.Name) and a.id == "initial_db_path":
                    found = True
    return found

def run_rule(code, initial_db, final_db):
    if not code or not isinstance(code, str) or len(code.strip()) < 10:
        return "judge_error", "no code"
    func_name = "verify_task_completion"
    for line in code.split("\n"):
        line = line.strip()
        if line.startswith("def verify_") and "(" in line:
            func_name = line.split("(")[0].replace("def ", "").strip(); break
    ns = {"sqlite3": sqlite3, "json": json, "os": os, "re": re, "__builtins__": __builtins__}
    try:
        exec(code, ns)
    except Exception as e:
        return "judge_error", f"exec: {type(e).__name__}: {e}"
    fn = ns.get(func_name)
    if not fn: return "judge_error", f"no func {func_name}"
    try:
        result = fn(initial_db, final_db, "")
    except Exception as e:
        return "judge_error", f"call: {type(e).__name__}: {e}"
    if not isinstance(result, dict) or "result" not in result:
        return "bad_return", str(result)[:80]
    rv = result.get("result", "others")
    return (rv if rv in ("complete","others") else "others"), ""

records = []
with open(f"{BASE}/gen_verifier.pure_code.jsonl") as f:
    lines = [json.loads(l) for l in f]

db_cache = {}
errors = []
for i, e in enumerate(lines):
    sn = norm(e.get("scenario",""))
    code = e.get("verification",{}).get("code","")
    ui = uses_initial(code)
    if sn not in db_cache:
        d = os.path.join(TMP, sn); os.makedirs(d, exist_ok=True)
        fdb = os.path.join(d, "final.db"); idb = os.path.join(d, "initial.db")
        build_db(sn, fdb)
        import shutil; shutil.copy2(fdb, idb)
        db_cache[sn] = (idb, fdb)
    idb, fdb = db_cache[sn]
    verdict, err = run_rule(code, idb, fdb)
    rec = dict(line=i, scenario=e.get("scenario",""), task_idx=e.get("task_idx"),
               verdict=verdict, err=err, uses_initial=ui,
               mentions_initial=("initial" in code.lower()), has_raw=bool(e.get("verification",{}).get("raw_response")))
    records.append(rec)
    if verdict in ("judge_error","bad_return"):
        errors.append(rec)
    if i % 1000 == 0: print(f"  line {i} done", file=sys.stderr)

with open("/tmp/awmdiag/sweep_records.json","w") as f:
    json.dump(records, f)

