print("\n=== originals (10000) cross-tab: uses_initial x no-op verdict ===")
ct = Counter((r["uses_initial"], r["verdict"]) for r in orig)
for k in sorted(ct, key=lambda x: (str(x[0]), x[1])):
    print(f"  uses_initial={k[0]!s:5}  verdict={k[1]:12s}  n={ct[k]}")
print("\n=== appended (10) ===")
for r in appended:
    print(f"  line {r['line']} {r['scenario']}/{r['task_idx']}  verdict={r['verdict']}  uses_initial={r['uses_initial']}  err={r['err'][:60]}")
print("\n=== judge_error / bad_return entries (all) ===")
for r in errors:
    print(f"  line {r['line']} {r['scenario']}/{r['task_idx']}  [{r['verdict']}]  {r['err'][:110]}")
EOF
